'use strict'

import HitboxManager from '../service/hitbox-manager'
import { isBlockedByQuarters } from '../service/collision'
import clock from '../service/clock'
import soundManager from '../service/sound-manager'
import resource from '../resource'
import { LINK_DIRECTION_EAST, LINK_DIRECTION_NORTH, LINK_DIRECTION_SOUTH, LINK_DIRECTION_WEST, LINK_ACTION_MOVE, LINK_ACTION_PICK, LINK_ACTION_USE, LINK_ACTION_USE_ITEM_A, LINK_ACTION_USE_ITEM_B, SPRITE_LINK_PREFIX, SWORDS, SWORD_DAMAGES, SOUND_SWORD_SLASH, SOUND_LINK_HURT, OPPOSITE_DIRECTIONS, ITEM_SHIELD_MAGICAL, ITEM_BOMB, SOUND_BOMB_DROP, TILE_WIDTH, TILE_HEIGHT, SWORD_HEARTS, MAX_HEARTS, ITEM_MAGICAL_SHIELD, ITEM_WOODEN_ARROW, ARROW_WOODEN, ITEM_BLUE_CANDLE, ITEM_KEY, ITEM_BAIT, ITEM_HEART, ITEM_HEART_CONTAINER, ITEM_BLUE_RING, ITEM_RING_BLUE, ITEM_RING_RED, ITEM_LETTER, ITEM_BLUE_POTION, ITEM_RED_POTION, CAVE_POTION_SHOP, SOUND_REFILL_LOOP, ITEM_RED_CANDLE, SOUND_CANDLE, ITEM_MAGICAL_SWORD, ARROW_SILVER, BOOK_OF_MAGIC, ITEM_LADDER, ITEM_MAGICAL_KEY, ITEM_POWER_BRACELET_NORMAL, INVENTORY_MAX_BOMBS, SWORD_PALETTES, SOUND_SWORD_SHOOT, ITEM_POWER_BRACELET, ITEM_WHISTLE, NES_PIXEL, ITEM_WOODEN_BOOMERANG, ITEM_MAGICAL_BOOMERANG, ITEM_BOW, ITEM_SILVER_ARROW, ITEM_WAND, ITEM_BOOK_OF_MAGIC, ITEM_RAFT, ITEM_RED_RING, ITEM_RUPEE, ITEM_FIVE_RUPESS, ITEM_FAIRY, ITEM_CLOCK, ITEM_DUNGEON_MAP, ITEM_DUNGEON_COMPASS, ITEM_TRIFORCE_FRAGMENT, MAP_TYPES_LEVELS, SOUND_BOOMERANG, SOUND_ARROW, SOUND_MAGICAL_ROD } from '../constant'
import { Boomerang, Arrow, Magic, Bait } from './weapons'
import { tryPutLadder, canTurnOnLadder, updateLadder, updateRaft, drawRaft } from './water'
import { Inventory } from './inventory'
import { createKillRecord, breakKillSeries } from './drop'
import { Item } from './item'
import { Bomb } from './bomb'
import { Flame } from './flame'
import { SwordBeam } from './beam'
import { tryPush, tryWakeArmos, frontTile } from './secret'
import { disturbGrave } from './enemies/ghini'
import { playWhistle, endWhistle, WHISTLE_STEPS } from './whistle'
import { directionOf } from './enemies/common'

const mod = (value, divisor) => ((value % divisor) + divisor) % divisor

const EVENT_ITEM_A_CHANGED = 'item_a_changed'
const EVENT_ITEM_B_CHANGED = 'item_b_changed'

// How long Link holds his sword out; he can't move meanwhile
const SWORD_DURATION = 250
// Putting a bomb down: 12 frames, measured in the ROM
const BOMB_DURATION = 200
// Lighting the candle: as long as putting a bomb down (not measured)
const CANDLE_DURATION = BOMB_DURATION
// Flames of the red candle burning at once (ROM: objects $10 and $11); the blue one burns once a screen
const MAX_FLAMES = 2
// No flame when Link is less than two tiles from the left or right edge of the screen (measured: from x = $20
// to $D0 only)
const CANDLE_EDGE = 2 * TILE_WIDTH
// How long the refill sound plays when Link drinks a potion
const POTION_SOUND_DURATION = 1000

const SPRITE_WIDTH = 32
const SPRITE_HEIGHT = 32

// Measured in the ROM: Link walks 8 NES pixels every 6 frames, 1, 2, 1, 2, 1 then 1 pixel a frame (doubled
// for the display), the count going on from one walk to the next
const WALK_STEPS = [1, 2, 1, 2, 1, 1].map(pixels => NES_PIXEL * pixels)
// He walks on a grid of 8 NES pixels: to turn, he first goes on to its nearest line (forward when he is
// half way), then turns (measured)
const GRID = TILE_WIDTH / 2
// With several arrows held, the order the ROM tries them on the grid, and the one off it (bank 5 $B2D5, and the
// routine $7013 of the cartridge RAM: the lowest bit of the arrows first)
const GRID_ORDER = [LINK_DIRECTION_NORTH, LINK_DIRECTION_SOUTH, LINK_DIRECTION_WEST, LINK_DIRECTION_EAST]
const OFF_GRID_ORDER = [LINK_DIRECTION_EAST, LINK_DIRECTION_WEST, LINK_DIRECTION_SOUTH, LINK_DIRECTION_NORTH]
// His legs move every 6 frames
const WALK_IMAGE_DURATION = 100
// When hurt, Link is pushed back (in game steps and pixels per step), then flickers, invincible
const KNOCKBACK_STEPS = 8
const KNOCKBACK_SPEED = 8
export const INVINCIBLE_STEPS = 48
// Meanwhile his colours change every 2 frames: his own, then those of the sprite palettes 3, 2 and 1 (measured)
const HURT_COLOURS = [undefined, 'hurt_dark', 'hurt_red', 'hurt_blue']
const HURT_COLOUR_STEPS = 2
const LINK_DEAD_COLOUR = 'dead'
// An enemy touches him 8 NES pixels away or less, across and along (measured on an octorok): his box for it is
// 6 NES pixels wide, the enemy's 12
const CONTACT_INSET = 10
// What enemies and rocks touch: the sprite, slightly smaller
const BODY_INSET = 4
// What the sword reaches, in front of Link, while he holds it out
const SWORD_REACH = 28
const SWORD_WIDTH = 16
// The sword held out, measured in the ROM (object $0D): nothing the first 4 frames, then out until frame 12,
// then drawn back in two frames. Places of its sprite from Link's, in NES pixels (doubled for the display)
const SWORD_OUT_STEP = 4
const SWORD_PLACES = {
  [LINK_DIRECTION_NORTH]: [[-1, -12], [-1, -11], [-1, -3]],
  [LINK_DIRECTION_SOUTH]: [[1, 11], [1, 7], [1, 3]],
  [LINK_DIRECTION_EAST]: [[11, 1], [7, 1], [3, 1]],
  [LINK_DIRECTION_WEST]: [[-11, 1], [-7, 1], [-3, 1]]
}
const SWORD_BACK_STEPS = [13, 14]
// With all his hearts, the sword flies off at frame 12, one at a time
const BEAM_STEP = 12
// The wand is held out 4 frames
const WAND_STEPS = 4

const DIRECTION_VECTORS = {
  [LINK_DIRECTION_EAST]: [1, 0],
  [LINK_DIRECTION_NORTH]: [0, -1],
  [LINK_DIRECTION_SOUTH]: [0, 1],
  [LINK_DIRECTION_WEST]: [-1, 0]
}

// An item of the B button, as shown in the menus
export function createBItem (name) {
  return new Item(name, 0, 0, 0, 0, TILE_WIDTH, TILE_HEIGHT, resource.getSprite(`item_${name}`))
}

class Link extends EventTarget {
  constructor (x, y, width, height) {
    super()

    this.x = x
    this.y = y
    this.width = SPRITE_WIDTH
    this.height = SPRITE_HEIGHT

    this.walkStep = 0 // In WALK_STEPS
    this.severalArrows = false // Several arrows held when he left the grid (see chooseWay)
    this.action = LINK_ACTION_MOVE
    this.direction = LINK_DIRECTION_SOUTH
    this.clipX = 0
    this.clipY = 0

    this.inventory = new Inventory()

    this.totalLife = 3
    this.currentLife = 3

    this.items = []
    this._itemA = undefined
    this._itemB = undefined

    this.actions = []
    this.usingItem = false
    this.swordSwing = 0 // Each thrust hits an enemy once
    this.swordSteps = 0 // Game steps since the thrust began
    this.bSteps = 0 // Game steps since he began using the item of B

    this.knockback = undefined
    this.invincibleSteps = 0
    // At the end of his death (grey)
    this.dead = false
    // Game steps of the whistle song left (Link stands still), the whirlwind carrying him, and the level it
    // went to last (index 0 to 7 of the level)
    this.whistleSteps = 0
    this.carried = undefined
    this.whirlwindLevel = 0
    // Sailing on the raft: { map, direction, dockY }
    this.raft = undefined
    // Enemies killed, for what they leave behind them
    this.killRecord = createKillRecord()
  }

  static get EVENT_ITEM_A_CHANGED () {
    return EVENT_ITEM_A_CHANGED
  }

  static get EVENT_ITEM_B_CHANGED () {
    return EVENT_ITEM_B_CHANGED
  }

  canPick (item) {
    if (!item.enabled || !item.pickable) {
      return false
    }

    const collision = HitboxManager.computeHitboxesCollision(item.hitbox, this.hitbox)
    if (!collision) {
      return false
    }

    if (item.price && this.inventory.rupees < item.price) {
      return false
    }

    // The old man keeps the sword until Link has enough hearts
    if (SWORD_HEARTS[item.name] && this.totalLife < SWORD_HEARTS[item.name]) {
      return false
    }

    return true
  }

  // Keeps a picked or bought item, as in the original game: swords go on the A button; the items of the
  // B button go there when it is free, and a better one takes the place of the one it replaces (red candle,
  // silver arrow, magical boomerang, potion instead of the letter)
  pickItem (item) {
    const inventory = this.inventory
    const before = inventory.bItems
    switch (item.name) {
      case ITEM_BOMB:
        this.addBombs(4)
        break
      case ITEM_MAGICAL_SHIELD:
        inventory.shield = ITEM_SHIELD_MAGICAL
        break
      case ITEM_WOODEN_ARROW:
        inventory.arrow ??= ARROW_WOODEN
        break
      case ITEM_SILVER_ARROW:
        inventory.arrow = ARROW_SILVER
        break
      case ITEM_BOW:
        inventory.bow = true
        break
      case ITEM_WOODEN_BOOMERANG:
        inventory.boomerang ??= ITEM_WOODEN_BOOMERANG
        break
      case ITEM_MAGICAL_BOOMERANG:
        inventory.boomerang = ITEM_MAGICAL_BOOMERANG
        break
      case ITEM_WAND:
        inventory.wand = true
        break
      case ITEM_BOOK_OF_MAGIC:
        inventory.bookOfMagic = BOOK_OF_MAGIC
        break
      case ITEM_LADDER:
        inventory.ladder = ITEM_LADDER
        break
      case ITEM_MAGICAL_KEY:
        inventory.magicalKey = ITEM_MAGICAL_KEY
        break
      case ITEM_RAFT:
        inventory.raft = true
        break
      case ITEM_BLUE_CANDLE:
        if (inventory.candle !== ITEM_RED_CANDLE) {
          inventory.candle = ITEM_BLUE_CANDLE
        }
        break
      case ITEM_RED_CANDLE:
        inventory.candle = ITEM_RED_CANDLE
        break
      case ITEM_RUPEE:
      case ITEM_FIVE_RUPESS:
        inventory.rupees = Math.min(inventory.maxRupees, inventory.rupees + (item.name === ITEM_RUPEE ? 1 : 5))
        break
      case ITEM_FAIRY:
        this.currentLife = Math.min(this.totalLife, this.currentLife + 3)
        break
      case ITEM_CLOCK:
        // The enemies of the screen stand still and harmless until Link leaves it
        if (this.map) {
          this.map.frozen = true
        }
        break
      case ITEM_RED_RING:
        inventory.ring = ITEM_RING_RED
        break
      case ITEM_DUNGEON_MAP:
      case ITEM_DUNGEON_COMPASS:
      case ITEM_TRIFORCE_FRAGMENT: {
        // Of the level Link is in
        const level = MAP_TYPES_LEVELS.indexOf(this.map?.type) + 1
        const levels = item.name === ITEM_DUNGEON_MAP ? inventory.maps : item.name === ITEM_DUNGEON_COMPASS ? inventory.compasses : inventory.triforce
        if (level > 0 && !levels.includes(level)) {
          levels.push(level)
          levels.sort((a, b) => a - b)
        }
        // A piece of the Triforce fills the hearts (measured in the ROM)
        if (item.name === ITEM_TRIFORCE_FRAGMENT) {
          this.currentLife = this.totalLife
        }
        break
      }
      case ITEM_BAIT:
        inventory.bait = true
        break
      case ITEM_KEY:
        inventory.keys = Math.min(inventory.maxKeys, inventory.keys + 1)
        break
      case ITEM_HEART:
        this.currentLife = Math.min(this.totalLife, this.currentLife + 1)
        break
      case ITEM_HEART_CONTAINER:
        // One more heart, filled (measured in the ROM)
        this.totalLife = Math.min(MAX_HEARTS, this.totalLife + 1)
        this.currentLife = Math.min(this.totalLife, this.currentLife + 1)
        break
      case ITEM_BLUE_RING:
        if (inventory.ring !== ITEM_RING_RED) {
          inventory.ring = ITEM_RING_BLUE
        }
        break
      case ITEM_POWER_BRACELET:
        inventory.powerBracelet = ITEM_POWER_BRACELET_NORMAL
        break
      case ITEM_LETTER:
        inventory.letter = true
        break
      case ITEM_WHISTLE:
        inventory.whistle = true
        break
      case ITEM_BLUE_POTION:
      case ITEM_RED_POTION:
        // The potion takes the place of the letter
        inventory.potion = Math.max(inventory.potion, item.name === ITEM_RED_POTION ? 2 : 1)
        inventory.letter = false
        break
      default:
        if (SWORDS.includes(item.name)) {
          const pickedItem = item.clone()
          pickedItem.price = undefined
          pickedItem.label = undefined
          this.addItem(pickedItem)
          this.itemA = pickedItem
        }
    }
    this.updateB(before)
  }

  // After the items of B changed (before: what each place of the inventory held): the item on B becomes the
  // one that took its place, and a new one goes on B when it is free
  updateB (before) {
    const after = this.inventory.bItems
    const replaced = before.indexOf(this.itemB?.name)
    if (replaced !== -1 && after[replaced] !== before[replaced]) {
      this.itemB = after[replaced] ? createBItem(after[replaced]) : undefined
    }
    const added = after.findIndex((name, index) => name && name !== before[index])
    if (added !== -1) {
      this.equipB(after[added])
    }
  }

  // Debug panel: the best of every item, the 8 pieces of the Triforce, full bomb bag and wallet, 16 hearts
  // filled. B keeps its item (or its better one), or gets the first item of the inventory
  giveAllItems () {
    const inventory = this.inventory
    const before = inventory.bItems
    this.items = this.items.filter(item => !SWORDS.includes(item.name))
    this.pickItem(createBItem(ITEM_MAGICAL_SWORD))
    inventory.shield = ITEM_SHIELD_MAGICAL
    inventory.ring = ITEM_RING_RED
    inventory.arrow = ARROW_SILVER
    inventory.bow = true
    inventory.boomerang = ITEM_MAGICAL_BOOMERANG
    inventory.wand = true
    inventory.bookOfMagic = BOOK_OF_MAGIC
    inventory.ladder = ITEM_LADDER
    inventory.raft = true
    inventory.magicalKey = ITEM_MAGICAL_KEY
    inventory.powerBracelet = ITEM_POWER_BRACELET_NORMAL
    inventory.candle = ITEM_RED_CANDLE
    inventory.bait = true
    inventory.whistle = true
    inventory.triforce = [1, 2, 3, 4, 5, 6, 7, 8]
    inventory.letter = false
    inventory.letterShown = true
    inventory.potion = 2
    inventory.maxBombs = INVENTORY_MAX_BOMBS[INVENTORY_MAX_BOMBS.length - 1]
    inventory.bombs = inventory.maxBombs
    inventory.rupees = inventory.maxRupees
    this.totalLife = MAX_HEARTS
    this.currentLife = MAX_HEARTS
    this.updateB(before)
  }

  // The potion owned: red while it has two uses left
  get potionName () {
    return this.inventory.potionName
  }

  // An item of B goes there when nothing is
  equipB (name) {
    if (name && this.itemB === undefined) {
      this.itemB = createBItem(name)
    }
  }

  // Sword thrust: Link stands still with the sword out for SWORD_DURATION
  useItemA () {
    if (this.itemA === undefined || this.usingItem) {
      return
    }
    this.usingItem = true
    this.swordSwing++
    this.swordSteps = 0
    this.stopWalking()
    this.action = LINK_ACTION_USE_ITEM_A
    soundManager.play(resource.getSound(SOUND_SWORD_SLASH))
    clock.delay(() => {
      this.usingItem = false
      this.action = LINK_ACTION_MOVE
    }, SWORD_DURATION)
  }

  get swordDamage () {
    return SWORD_DAMAGES[this.itemA?.name] ?? 0
  }

  // What an enemy touches
  getContactBox () {
    return { x: this.x + CONTACT_INSET, y: this.y + CONTACT_INSET, width: this.width - 2 * CONTACT_INSET, height: this.height - 2 * CONTACT_INSET }
  }

  getBodyBox () {
    return { x: this.x + BODY_INSET, y: this.y + BODY_INSET, width: this.width - 2 * BODY_INSET, height: this.height - 2 * BODY_INSET }
  }

  // The blade in front of Link during a thrust, undefined otherwise
  getSwordBox () {
    if (!this.usingItem || this.action !== LINK_ACTION_USE_ITEM_A) {
      return undefined
    }
    const across = (this.width - SWORD_WIDTH) / 2
    switch (this.direction) {
      case LINK_DIRECTION_NORTH:
        return { x: this.x + across, y: this.y - SWORD_REACH, width: SWORD_WIDTH, height: SWORD_REACH }
      case LINK_DIRECTION_SOUTH:
        return { x: this.x + across, y: this.y + this.height, width: SWORD_WIDTH, height: SWORD_REACH }
      case LINK_DIRECTION_EAST:
        return { x: this.x + this.width, y: this.y + across, width: SWORD_REACH, height: SWORD_WIDTH }
      case LINK_DIRECTION_WEST:
        return { x: this.x - SWORD_REACH, y: this.y + across, width: SWORD_REACH, height: SWORD_WIDTH }
    }
  }

  // The shield stops what comes at Link from the front, unless he is busy with his sword or pushed back
  // Some projectiles (lynel swords, fireballs) are only stopped by this one
  get hasMagicalShield () {
    return this.inventory.shield === ITEM_SHIELD_MAGICAL
  }

  canBlock (direction) {
    return !this.usingItem && !this.knockback && this.direction === OPPOSITE_DIRECTIONS[direction]
  }

  // Hurt by something at source (a box): loses life and is pushed away from it. True if he was hurt
  hurt (damage, source) {
    if (this.invincibleSteps > 0 || this.carried) {
      return false
    }
    // The blue ring halves the damage, the red one quarters it
    damage /= this.inventory.ring === ITEM_RING_RED ? 4 : this.inventory.ring === ITEM_RING_BLUE ? 2 : 1
    this.currentLife = Math.max(0, this.currentLife - damage)
    this.invincibleSteps = INVINCIBLE_STEPS
    breakKillSeries(this.killRecord)
    soundManager.play(resource.getSound(SOUND_LINK_HURT))
    // Measured in the ROM: down when what hurt him is 5 NES pixels above him or more, up when it is 3 below him
    // or more, sideways otherwise (west when it is right on him)
    const dx = source.x + source.width / 2 - (this.x + this.width / 2)
    const dy = source.y + source.height / 2 - (this.y + this.height / 2)
    const vector = dy <= -10 ? [0, 1] : dy >= 6 ? [0, -1] : [dx >= 0 ? -1 : 1, 0]
    this.knockback = { vector, steps: KNOCKBACK_STEPS }
    this.stopWalking()

    return true
  }

  // One game step of what happens to Link on his own: being pushed back, invincibility running out, the
  // whistle song. He stays on the screen when pushed (no screen change)
  update (map) {
    // On the raft, from a dock or to it (see water.js)
    updateRaft(map, this)
    if (this.invincibleSteps > 0) {
      this.invincibleSteps--
    }
    if (this.whistleSteps > 0) {
      this.whistleSteps--
      if (this.whistleSteps === 0) {
        this.usingItem = false
        endWhistle(map, this)
      }
    }
    if (this.usingItem && this.action === LINK_ACTION_USE_ITEM_B) {
      this.bSteps++
    }
    if (this.usingItem && this.action === LINK_ACTION_USE_ITEM_A) {
      this.swordSteps++
      if (this.swordSteps === BEAM_STEP) {
        this.shootBeam(map)
      }
    }
    if (!this.knockback) {
      return
    }
    const [dx, dy] = this.knockback.vector
    for (let i = 0; i < KNOCKBACK_SPEED; i++) {
      const x = this.x + dx
      const y = this.y + dy
      const inside = map.x <= x && x + this.width <= map.x + map.width && map.y <= y && y + this.height <= map.y + map.height
      if (!inside || !this.moveBy(map, dx, dy)) {
        break
      }
    }
    this.hitbox = HitboxManager.compute(this)
    this.knockback.steps--
    if (this.knockback.steps <= 0) {
      this.knockback = undefined
    }
  }

  // The sword flies off when Link has all his hearts, if the last one is gone
  shootBeam (map) {
    if (this.currentLife < this.totalLife || map.beams.length > 0 || this.hasThrown(map, Magic)) {
      return
    }
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    const [x, y] = SWORD_PLACES[this.direction][0]
    map.beams.push(new SwordBeam(this.x + NES_PIXEL * x, this.y + NES_PIXEL * y, this.direction, [dx, dy], this.swordDamage))
    soundManager.play(resource.getSound(SOUND_SWORD_SHOOT))
  }

  // The item of the B button
  useItemB (map) {
    switch (this.itemB?.name) {
      case ITEM_WOODEN_BOOMERANG:
      case ITEM_MAGICAL_BOOMERANG:
        this.throwBoomerang(map)
        break
      case ITEM_WOODEN_ARROW:
      case ITEM_SILVER_ARROW:
        this.shootArrow(map)
        break
      case ITEM_WAND:
        this.waveWand(map)
        break
      case ITEM_BAIT:
        this.putBait(map)
        break
      case ITEM_BOMB:
        this.putBomb(map)
        break
      case ITEM_BLUE_CANDLE:
      case ITEM_RED_CANDLE:
        this.lightCandle(map)
        break
      case ITEM_WHISTLE:
        this.playWhistle(map)
        break
      case ITEM_LETTER:
        // Shown to the old woman, it opens the potion shops for good
        if (map.cave === CAVE_POTION_SHOP) {
          this.inventory.letterShown = true
        }
        break
      case ITEM_BLUE_POTION:
      case ITEM_RED_POTION:
        this.drinkPotion()
        break
    }
  }

  // Life back to full; a red potion becomes a blue one, a blue one is gone
  drinkPotion () {
    if (this.inventory.potion <= 0 || this.usingItem) {
      return
    }
    this.currentLife = this.totalLife
    this.inventory.potion--
    this.itemB = this.potionName ? createBItem(this.potionName) : undefined
    const sound = resource.getSound(SOUND_REFILL_LOOP)
    soundManager.play(sound)
    if (sound) {
      clock.delay(() => soundManager.stop(sound), POTION_SOUND_DURATION)
    }
  }

  // Link stands still a moment, in the pose of the sword, while he uses an item of B
  holdStill (duration = BOMB_DURATION) {
    this.usingItem = true
    this.stopWalking()
    this.action = LINK_ACTION_USE_ITEM_B
    this.bSteps = 0
    clock.delay(() => {
      this.usingItem = false
      this.action = LINK_ACTION_MOVE
    }, duration)
  }

  // Where what Link throws starts: the tile in front of him
  get frontPlace () {
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    return [this.x + dx * TILE_WIDTH, this.y + dy * TILE_HEIGHT]
  }

  // The boomerang and the bait are the same object of the ROM ($0F): one of them at a time
  hasThrown (map, ...kinds) {
    return map.weapons.some(weapon => kinds.some(kind => weapon instanceof kind))
  }

  throwBoomerang (map) {
    if (this.usingItem || this.hasThrown(map, Boomerang, Bait)) {
      return
    }
    map.weapons.push(new Boomerang(...this.frontPlace, this.direction, this.itemB.name))
    soundManager.play(resource.getSound(SOUND_BOOMERANG))
    this.holdStill()
  }

  // An arrow costs a rupee: none without one
  shootArrow (map) {
    if (this.usingItem || this.inventory.rupees <= 0 || this.hasThrown(map, Arrow)) {
      return
    }
    this.inventory.rupees--
    map.weapons.push(new Arrow(...this.frontPlace, this.direction, this.inventory.arrow))
    soundManager.play(resource.getSound(SOUND_ARROW))
    this.holdStill()
  }

  // The magic goes the way of the flying sword ($0E): not while one flies
  waveWand (map) {
    if (this.usingItem || map.beams.length > 0 || this.hasThrown(map, Magic)) {
      return
    }
    map.weapons.push(new Magic(...this.frontPlace, this.direction, Boolean(this.inventory.bookOfMagic)))
    soundManager.play(resource.getSound(SOUND_MAGICAL_ROD))
    this.holdStill()
  }

  putBait (map) {
    if (this.usingItem || this.hasThrown(map, Boomerang, Bait)) {
      return
    }
    map.weapons.push(new Bait(...this.frontPlace))
    this.holdStill()
  }

  // A bomb on the ground, one tile in front of Link (even in a wall), one at a time
  putBomb (map) {
    if (this.usingItem || this.inventory.bombs <= 0 || map.bombs.length > 0) {
      return
    }
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    map.bombs.push(new Bomb(this.x + dx * TILE_WIDTH, this.y + dy * TILE_HEIGHT))
    this.inventory.bombs--
    if (this.inventory.bombs === 0) {
      this.itemB = undefined
    }
    soundManager.play(resource.getSound(SOUND_BOMB_DROP))
    this.usingItem = true
    this.stopWalking()
    this.action = LINK_ACTION_USE_ITEM_B
    clock.delay(() => {
      this.usingItem = false
      this.action = LINK_ACTION_MOVE
    }, BOMB_DURATION)
  }

  // A flame one tile in front of Link, which goes one more tile and burns there (bushes, enemies). The
  // blue candle lights one a screen, the red one as many as Link wants, two at a time (measured in the ROM)
  lightCandle (map) {
    if (this.usingItem || map.flames.length >= MAX_FLAMES) {
      return
    }
    const fromLeft = this.x - map.x
    if ((this.direction === LINK_DIRECTION_WEST && fromLeft < CANDLE_EDGE) || (this.direction === LINK_DIRECTION_EAST && fromLeft > map.width - this.width - CANDLE_EDGE)) {
      return
    }
    const red = this.inventory.candle === ITEM_RED_CANDLE
    if (!red && (map.candleUsed || map.flames.length > 0)) {
      return
    }
    map.candleUsed = true
    const vector = DIRECTION_VECTORS[this.direction]
    map.flames.push(new Flame(this.x + vector[0] * TILE_WIDTH, this.y + vector[1] * TILE_HEIGHT, vector))
    soundManager.play(resource.getSound(SOUND_CANDLE))
    this.usingItem = true
    this.stopWalking()
    this.action = LINK_ACTION_USE_ITEM_B
    clock.delay(() => {
      this.usingItem = false
      this.action = LINK_ACTION_MOVE
    }, CANDLE_DURATION)
  }

  // Link plays the whistle, standing still as he is (no other pose, measured in the ROM); what it does
  // comes when the song ends (see whistle.js)
  playWhistle (map) {
    if (this.usingItem || this.carried || !playWhistle(map)) {
      return
    }
    this.whistleSteps = WHISTLE_STEPS
    this.usingItem = true
    this.stopWalking()
  }

  // Bombs picked or bought, up to what the bag holds. With nothing on B, they go there
  addBombs (count) {
    this.inventory.bombs = Math.min(this.inventory.maxBombs, this.inventory.bombs + count)
    if (this.inventory.bombs > 0 && this.itemB === undefined) {
      this.itemB = createBItem(ITEM_BOMB)
    }
  }

  // Collision box: the lower half of the sprite (his feet), as in the ROM
  getHitbox (x = this.x, y = this.y) {
    return { x, y: y + this.height / 2, width: this.width, height: this.height / 2 }
  }

  // The way Link goes for the arrows held, as in the ROM (bank 5, $B29A):
  // - on the grid, one arrow: that way. Two or more: of those whose next tile is free, up, then down, left,
  //   right (if none is free, the same order); and as long as he has not got back on the grid, he goes on
  //   whatever else is held
  // - off the grid: the arrow held first in the order right, left, down, up. His way or its opposite: that
  //   way. Across it: on, if two arrows were held on the grid or if he has gone half the grid already (4 NES
  //   pixels), otherwise back to the line he left
  chooseWay (map, held) {
    const offsetX = mod(this.x - map.x, GRID)
    const offsetY = mod(this.y - map.y, GRID)
    if (offsetX === 0 && offsetY === 0) {
      this.severalArrows = false
      if (held.length === 1) {
        return held[0]
      }
      const free = held.filter(direction => this.canStep(map, direction))
      this.severalArrows = free.length > 0
      return GRID_ORDER.find(direction => (free.length ? free : held).includes(direction))
    }
    const wanted = OFF_GRID_ORDER.find(direction => held.includes(direction))
    const facing = this.direction
    const horizontal = facing === LINK_DIRECTION_EAST || facing === LINK_DIRECTION_WEST
    // Off the grid across his way (pushed back): the nearest line (see move)
    if ((horizontal ? offsetY : offsetX) !== 0) {
      return wanted
    }
    if (wanted === facing || wanted === OPPOSITE_DIRECTIONS[facing] || this.severalArrows) {
      return wanted === OPPOSITE_DIRECTIONS[facing] ? wanted : facing
    }
    const offset = horizontal ? offsetX : offsetY
    const gone = facing === LINK_DIRECTION_EAST || facing === LINK_DIRECTION_SOUTH ? offset : GRID - offset
    return gone >= GRID / 2 ? facing : OPPOSITE_DIRECTIONS[facing]
  }

  // The next tile that way does not stop him (the ROM looks at one tile ahead, bank 7 $EDFA)
  canStep (map, direction) {
    const [dx, dy] = DIRECTION_VECTORS[direction]
    return !isBlockedByQuarters(map, this.getHitbox(this.x + dx, this.y + dy), map.ladder)
  }

  // Walks the way chosen for the arrows held (see chooseWay)
  walk (map, held) {
    this.move(map, this.chooseWay(map, held))
  }

  // Moves pixel by pixel, so Link stops flush against walls. Off the grid across the way he wants to go, he
  // first goes along it to its nearest line, facing that way. No help round the corners: in the ROM, the grid
  // is all. Stopped by a rock hiding an entrance, he pushes it; walking into an Armos statue wakes it
  move (map, direction) {
    // On the ladder, only along it
    if (!canTurnOnLadder(map, this, direction)) {
      return
    }
    let [dx, dy] = DIRECTION_VECTORS[direction]
    let distance = WALK_STEPS[this.walkStep]
    this.walkStep = (this.walkStep + 1) % WALK_STEPS.length
    const offset = dx !== 0 ? mod(this.y - map.y, GRID) : mod(this.x - map.x, GRID)
    if (offset !== 0) {
      const [facingX, facingY] = DIRECTION_VECTORS[this.direction]
      const facing = dx !== 0 ? facingY : facingX
      const sign = offset < GRID / 2 ? -1 : offset > GRID / 2 ? 1 : facing || 1
      distance = Math.min(distance, sign > 0 ? GRID - offset : offset)
      ;[dx, dy] = dx !== 0 ? [0, sign] : [sign, 0]
      direction = directionOf(dx, dy)
    }
    this.direction = direction
    let blocked = false
    for (let i = 0; i < distance; i++) {
      if (!this.moveBy(map, dx, dy)) {
        blocked = true
        tryWakeArmos(map, this)
        tryPush(map, this)
        tryPutLadder(map, this, direction, frontTile(map, this))
        break
      }
    }
    updateLadder(map, this)
    // Pushing a grave of a graveyard brings out a ghini (see ghini.js)
    disturbGrave(map, this, blocked ? frontTile(map, this) : undefined)

    this.hitbox = HitboxManager.compute(this)
  }

  moveBy (map, dx, dy) {
    if (isBlockedByQuarters(map, this.getHitbox(this.x + dx, this.y + dy), map.ladder)) {
      return false
    }
    this.x += dx
    this.y += dy

    return true
  }

  startWalking () {
    const sprite = resource.getSprite(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${this.action}`)
    if (!sprite) {
      console.log(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${this.action}`)
      return
    }
    sprite.incrementSpeed = WALK_IMAGE_DURATION
    sprite.start()
  }

  stopWalking () {
    const sprite = resource.getSprite(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${this.action}`)
    if (!sprite) {
      console.log(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${this.action}`)
      return
    }
    sprite.stop()
  }

  // Standing still whatever the direction, on the first image of the walk: each direction has its own
  // sprite, which may still be animated after Link turned (he spins when he dies)
  standStill () {
    for (const direction of Object.keys(OPPOSITE_DIRECTIONS)) {
      const sprite = resource.getSprite(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${direction}_${this.inventory.shield}_${LINK_ACTION_MOVE}`)
      sprite?.stop()
      if (sprite) {
        sprite.currentImageIndex = 0
      }
    }
  }

  // The sword in front of Link, in the colours of the sword (not the item on the ground)
  drawSword (context, offsetX, offsetY) {
    if (this.swordSteps < SWORD_OUT_STEP) {
      return
    }
    const back = SWORD_BACK_STEPS.indexOf(this.swordSteps)
    const [x, y] = SWORD_PLACES[this.direction][back + 1]
    const sprite = resource.getSprite(`sword_${SWORD_PALETTES[this.itemA.name] ?? 'green'}_${this.direction}`)
    sprite?.draw(context, offsetX + this.x + NES_PIXEL * x, offsetY + this.y + NES_PIXEL * y, TILE_WIDTH, TILE_HEIGHT)
  }

  // The wand in front of Link, drawn back like the sword (measured: object $12, states $32 to $35, at the places of
  // the sword drawn back, then gone)
  drawWand (context, offsetX, offsetY) {
    if (this.bSteps >= WAND_STEPS) {
      return
    }
    const [x, y] = SWORD_PLACES[this.direction][Math.min(this.bSteps, 2)]
    resource.getSprite(`wand_${this.direction}`)?.draw(context, offsetX + this.x + NES_PIXEL * x, offsetY + this.y + NES_PIXEL * y, TILE_WIDTH, TILE_HEIGHT)
  }

  // His colours: those of his ring, or, while invincible, the ones he flashes in
  get colour () {
    // Grey once dead (palette of the ROM)
    if (this.dead) {
      return LINK_DEAD_COLOUR
    }
    if (this.invincibleSteps <= 0) {
      return this.inventory.ring
    }
    const steps = INVINCIBLE_STEPS - this.invincibleSteps
    return HURT_COLOURS[Math.floor(steps / HURT_COLOUR_STEPS) % HURT_COLOURS.length] ?? this.inventory.ring
  }

  draw (context, offsetX, offsetY, drawingAction) {
    // Not seen in the whirlwind
    if (this.carried) {
      return
    }

    if (this.raft) {
      drawRaft(context, this, offsetX, offsetY)
    }
    if (drawingAction === LINK_ACTION_USE_ITEM_A) {
      this.drawSword(context, offsetX, offsetY)
    }
    if (drawingAction === LINK_ACTION_USE_ITEM_B && this.itemB?.name === ITEM_WAND) {
      this.drawWand(context, offsetX, offsetY)
    }

    const spriteName = this.getSpriteName(drawingAction)
    // Not every ring / shield has its own sprite for each action: fall back on the walking one
    const ringSprite = resource.getSprite(spriteName) ?? resource.getSprite(this.getSpriteName(LINK_ACTION_MOVE))
    if (!ringSprite) {
      console.log(spriteName)
      return
    }
    // Flashing: the same image of the walk, in the other colours
    const colour = this.colour
    const sprite = colour === this.inventory.ring ? ringSprite : resource.getSprite(this.getSpriteName(drawingAction, colour)) ?? ringSprite
    sprite.currentImageIndex = ringSprite.currentImageIndex
    sprite.draw(
      context,
      0, 0, this.width - this.clipX, this.height - this.clipY,
      offsetX + this.x + this.clipX, offsetY + this.y + this.clipY, this.width - this.clipX, this.height - this.clipY
    )
  }

  getSpriteName (action, colour = this.inventory.ring) {
    switch (action) {
      case LINK_ACTION_PICK:
        return `${SPRITE_LINK_PREFIX}_${colour}_${LINK_ACTION_PICK}`
      case LINK_ACTION_USE_ITEM_A:
      case LINK_ACTION_USE_ITEM_B:
        return `${SPRITE_LINK_PREFIX}_${colour}_${this.direction}_${this.inventory.shield}_${LINK_ACTION_USE}`
      case LINK_ACTION_MOVE:
        return `${SPRITE_LINK_PREFIX}_${colour}_${this.direction}_${this.inventory.shield}_${LINK_ACTION_MOVE}`
    }
  }

  addItem (item) {
    this.items.push(item)
  }

  // Items are compared by name (wooden_sword…): the picked item is a copy of the one on the map
  removeItem (item) {
    this.items = this.items.filter(ownedItem => ownedItem.name !== item.name)
  }

  hasItem (item) {
    return this.items.some(ownedItem => ownedItem.name === item.name)
  }

  addAction (action) {
    if (this.actions.indexOf(action) === -1) {
      this.actions.push(action)
    }
  }

  hasAction (action) {
    return this.actions.indexOf(action) > -1
  }

  removeAction (action) {
    const index = this.actions.indexOf(action)
    if (index > -1) {
      this.actions.splice(index, 1)
    }
  }

  resetActions () {
    this.actions = []
  }

  get itemA () {
    return this._itemA
  }

  set itemA (item) {
    this._itemA = item
    this.dispatchEvent(new Event(EVENT_ITEM_A_CHANGED))
  }

  get itemB () {
    return this._itemB
  }

  set itemB (item) {
    this._itemB = item
    this.dispatchEvent(new Event(EVENT_ITEM_B_CHANGED))
  }
}

export default Link
