'use strict'

import { CAVE_MONEY_GAME, CAVE_PAY_TO_TALK, CAVE_POTION_SHOP } from '../constant'

// What each kind of cave does (see CAVES in constant.js and docs/rom-analysis.md, Cavernes)

// The money making game, as in the ROM (bank 1, $864B): one rupee wins 20 or 50, one loses 10, one loses
// 10 or 40, in one of 6 orders (tables $85B6, $85B8, $85CA)
const MONEY_GAME_ORDERS = [[0, 1, 2], [1, 2, 0], [2, 0, 1], [0, 2, 1], [2, 1, 0], [1, 0, 2]]
// A random byte above which the next order is taken, from 255 down by $2B: the first order comes a
// little less often (41 bytes out of 256, 43 for the others)
const MONEY_GAME_ORDER_STEP = 0x2b

const randomByte = random => Math.floor(random() * 256)

// The three values hidden under the rupees, left to right
export function drawMoneyGame (random = Math.random) {
  const orderByte = randomByte(random)
  // 255 is never below the byte: the order is at most the last one
  let order = MONEY_GAME_ORDERS.length
  for (let threshold = 0xff; order > 0 && threshold >= orderByte; threshold -= MONEY_GAME_ORDER_STEP) {
    order--
  }
  // Two bits of another random byte: the second loss, and the gain
  const valuesByte = randomByte(random)
  const values = [valuesByte & 1 ? -40 : -10, -10, valuesByte & 2 ? 50 : 20]
  return MONEY_GAME_ORDERS[order].map(index => values[index])
}

export function formatSigned (value) {
  return value > 0 ? `+${value}` : `${value}`
}

// What is written under an item: its price, or what it costs to play or to talk
export function getPriceLabel (cave, price) {
  if (!price) {
    return undefined
  }
  return cave === CAVE_MONEY_GAME || cave === CAVE_PAY_TO_TALK ? `-${price}` : `${price}`
}

// The potion shop shows nothing until Link has shown the letter there
export function isCaveClosed (map, link) {
  return map.cave === CAVE_POTION_SHOP && !link.inventory.letterShown
}
