'use strict'

import { isBlocked, isBlockedByQuarters } from '../../service/collision'
import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { overlaps } from '../../utils/box'
import { chooseDrop, Drop } from '../drop'
import { TILE_WIDTH, TILE_HEIGHT, DIRECTION_EAST, DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_WEST, SOUND_ENNEMY_HIT, SOUND_ENNEMY_DIE } from '../../constant'

// Everything is counted in game steps (60 per second) and display pixels (twice the NES ones).
// The values follow the behaviour of the original game, measured by eye: they are approximations

export const DIRECTION_VECTORS = {
  [DIRECTION_EAST]: [1, 0],
  [DIRECTION_NORTH]: [0, -1],
  [DIRECTION_SOUTH]: [0, 1],
  [DIRECTION_WEST]: [-1, 0]
}
export const DIRECTIONS = Object.keys(DIRECTION_VECTORS)

export const CLOUD_FRAME_STEPS = 8
export const DEATH_FRAME_STEPS = 6
// Hit, an enemy waits a frame, then is pushed back 4 NES pixels a frame for 16 frames, the way Link strikes, its
// own way whatever (measured in the ROM on moblins, octoroks, lynels); on the grid, the scenery ahead stops it as
// it stops the walkers (see canWalkTo)
export const KNOCKBACK_WAIT = 1
export const KNOCKBACK_STEPS = KNOCKBACK_WAIT + 16
export const KNOCKBACK_SPEED = 8
export const BODY_INSET = 4
export const TERRAIN_INSET = 2
// A boomerang stuns an enemy for 160 frames (measured in the ROM on a red octorok: $3D + slot)
export const STUN_STEPS = 160

export const STATE_WAITING = 'waiting'
export const STATE_SPAWNING = 'spawning'
export const STATE_HURT = 'hurt'
export const STATE_DYING = 'dying'
export const STATE_DEAD = 'dead'

export function randomInt (random, min, max) {
  return min + Math.floor(random() * (max - min + 1))
}

export function pick (random, values) {
  return values[Math.floor(random() * values.length)]
}

export function shuffle (random, values) {
  const shuffled = [...values]
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
  }

  return shuffled
}

export function inset (x, y, width, height, value) {
  return { x: x + value, y: y + value, width: width - 2 * value, height: height - 2 * value }
}

export function isInside (map, x, y, width, height) {
  return map.x <= x && x + width <= map.x + map.width && map.y <= y && y + height <= map.y + map.height
}

// Free for a tile sized body (not in a wall, on the screen)
export function isFree (map, x, y) {
  return isInside(map, x, y, TILE_WIDTH, TILE_HEIGHT) && !isBlocked(map, inset(x, y, TILE_WIDTH, TILE_HEIGHT, TERRAIN_INSET))
}

// On the grid, the ROM looks at the scenery one tile ahead (bank 7, $EDFA), at quarters of it only: the bottom
// left one of the tile beside it, the bottom ones of the tile above, the top ones of the tile below. Then it
// goes the whole tile without looking again, brushing past the corners of the rocks. Quarters as [column, line]
const PROBES = {
  east: [[0, 1]],
  west: [[0, 1]],
  north: [[0, 1], [1, 1]],
  south: [[0, 0], [1, 0]]
}

// From a point of the grid, a body of a tile can go to the next tile that way: it is on the screen and its probed
// quarters are free (see PROBES)
export function canWalkTo (map, x, y, direction) {
  const [dx, dy] = DIRECTION_VECTORS[direction]
  const toX = x + dx * TILE_WIDTH
  const toY = y + dy * TILE_HEIGHT
  if (!isInside(map, toX, toY, TILE_WIDTH, TILE_HEIGHT)) {
    return false
  }
  const quarter = { width: TILE_WIDTH / 2, height: TILE_HEIGHT / 2 }
  return PROBES[direction].every(([column, line]) => !isBlockedByQuarters(map, { ...quarter, x: toX + column * quarter.width, y: toY + line * quarter.height }))
}

export function drawImage (context, sprite, index, x, y, width, height) {
  sprite?.images[index]?.draw(context, x, y, width, height)
}

// The cardinal direction closest to a vector
export function directionOf (dx, dy) {
  if (Math.abs(dx) >= Math.abs(dy)) {
    return dx >= 0 ? DIRECTION_EAST : DIRECTION_WEST
  }
  return dy >= 0 ? DIRECTION_SOUTH : DIRECTION_NORTH
}

// What all enemies share: appearing in a cloud, being hit by the sword (pushed back, then dying),
// hurting Link on contact. A kind of enemy says what it does the rest of the time (act) and how it
// looks (drawBody); while hurt, it goes back to `resumeState` afterwards
export class Enemy {
  constructor (type, x, y, { life, contactDamage }, random = Math.random) {
    this.type = type
    this.x = x
    this.y = y
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.life = life
    this.contactDamage = contactDamage
    this.random = random

    this.state = undefined
    this.steps = 0 // In the current state
    this.resumeState = undefined
    this.knockbackDirection = undefined
    this.lastSwing = undefined
    this.drop = undefined // What it leaves when dead
    this.stunSteps = 0
  }

  get isDead () {
    return this.state === STATE_DEAD
  }

  // Hurts Link when touching him
  get isActive () {
    return ![STATE_WAITING, STATE_SPAWNING, STATE_DYING, STATE_DEAD].includes(this.state)
  }

  // Can be hit by the sword
  get isVulnerable () {
    return this.isActive && this.state !== STATE_HURT
  }

  setState (state) {
    this.state = state
    this.steps = 0
  }

  getBox () {
    return inset(this.x, this.y, this.width, this.height, BODY_INSET)
  }

  // Where the enemy can go: free ground by default
  canStandAt (map, x, y) {
    return isFree(map, x, y)
  }

  // After the cloud
  start (map) {}

  knockBack (map) {
    if (this.steps <= KNOCKBACK_WAIT) {
      return
    }
    const direction = this.knockbackDirection
    const [dx, dy] = DIRECTION_VECTORS[direction]
    for (let i = 0; i < KNOCKBACK_SPEED; i++) {
      const onGrid = dx !== 0 ? (this.x - map.x) % TILE_WIDTH === 0 : (this.y - map.y) % TILE_HEIGHT === 0
      if ((onGrid && !canWalkTo(map, this.x, this.y, direction)) || !isInside(map, this.x + dx, this.y + dy, this.width, this.height)) {
        break
      }
      this.x += dx
      this.y += dy
    }
  }

  // By the sword of Link by default, or by something else (a bomb): its damage, the way it pushes
  hit (link, { damage, direction, byBomb } = {}) {
    if (damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    this.life -= damage ?? link.swordDamage
    if (this.life <= 0) {
      soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
      this.drop = chooseDrop(this.type, link.killRecord, this.random, byBomb)
      this.setState(STATE_DYING)
      return
    }
    soundManager.play(resource.getSound(SOUND_ENNEMY_HIT))
    this.knockbackDirection = direction ?? link.direction
    this.resumeState = this.state
    this.setState(STATE_HURT)
  }

  // The states every enemy has; false for the others (the enemy's own)
  processCommon (map) {
    switch (this.state) {
      case STATE_SPAWNING:
        if (this.steps >= 3 * CLOUD_FRAME_STEPS) {
          this.start(map)
        }
        return true
      case STATE_HURT:
        this.knockBack(map)
        if (this.steps >= KNOCKBACK_STEPS) {
          this.setState(this.resumeState)
        }
        return true
      case STATE_DYING:
        if (this.steps >= 3 * DEATH_FRAME_STEPS) {
          this.setState(STATE_DEAD)
          if (this.drop) {
            map.drops.push(new Drop(this.drop, this.x, this.y, this.random))
          }
        }
        return true
      case STATE_DEAD:
        return true
    }
    return false
  }

  act (map, link) {}

  // It hurt Link by touching him: in the ROM, the walkers and the leevers go back then (measured on an octorok)
  turnBack () {}

  // The sword first: a hit enemy does not hurt Link in the same step. Under the clock, it is harmless
  fight (map, link) {
    const swordBox = link.getSwordBox()
    if (swordBox && this.isVulnerable && link.swordSwing !== this.lastSwing && overlaps(swordBox, this.getBox())) {
      this.hit(link)
      return
    }
    if (this.isActive && !map.frozen && overlaps(this.getBox(), link.getContactBox()) && link.hurt(this.contactDamage, this.getBox())) {
      this.turnBack()
    }
  }

  // Hit by a boomerang: it stands still a while, and hurts Link all the same
  stun () {
    this.stunSteps = STUN_STEPS
  }

  process (map, link) {
    this.steps++
    const stunned = this.stunSteps > 0
    if (stunned) {
      this.stunSteps--
    }
    // Standing still under the clock, or stunned
    if (!this.processCommon(map) && !map.frozen && !stunned) {
      this.act(map, link)
    }
    this.fight(map, link)
  }

  drawBody (context) {}

  draw (context) {
    switch (this.state) {
      case STATE_WAITING:
      case STATE_DEAD:
        return
      case STATE_SPAWNING:
        drawImage(context, resource.getSprite('misc_bomb_blow'), Math.floor(this.steps / CLOUD_FRAME_STEPS), this.x, this.y, this.width, this.height)
        return
      case STATE_DYING:
        drawImage(context, resource.getSprite('death'), Math.floor(this.steps / DEATH_FRAME_STEPS), this.x, this.y, this.width, this.height)
        return
      case STATE_HURT:
        // Flickers while pushed back
        if (Math.floor(this.steps / 2) % 2 === 1) {
          return
        }
    }
    this.drawBody(context)
  }
}
