'use strict'

// NES colours (index 0x00 to 0x3f): Nestopia palette, with the 6 shades the former sheet used. Shared by the sprite
// builder (tools/sprites/build.js) and the game (colours of the screen while Link dies)
export const NES_COLOURS = [
  '666666', '002a88', '1412a7', '3b00a4', '5c007e', '6e0040', '6c0600', '561d00', '333500', '0b4800', '005200', '004f08', '183c5c', '000000', '000000', '000000',
  'adadad', '155fd9', '4240ff', '7527fe', 'a01acc', 'b71e7b', 'b53120', '994e00', '6b6d00', '388700', '0d9300', '008f32', '008088', '000000', '000000', '000000',
  'ffffff', '64b0ff', '9290ff', 'c676ff', 'f36aff', 'fe6ecc', 'fe8170', 'ea9e22', 'bcbe00', '88d800', '5ce430', '45e082', '00e8d8', '4f4f4f', '000000', '000000',
  'ffffff', 'c0dfff', 'd3d2ff', 'e8c8ff', 'fbc2ff', 'fec4ea', 'ffccc5', 'f7d8a5', 'e4e594', 'cfef96', 'bdf4ab', 'b3f3cc', 'b5ebf2', 'b8b8b8', '000000', '000000'
]

// The NES colour of an "rrggbb" colour: black is 0x0f, white 0x30, as the game uses them
const CODES = new Map([['000000', 0x0f], ['ffffff', 0x30]])
NES_COLOURS.forEach((colour, code) => { if (!CODES.has(colour)) CODES.set(colour, code) })

export function nesCode (colour) {
  return CODES.get(colour)
}
